#!/usr/bin/env python3
"""SRT subtitle parser and re-timer."""

import argparse
import re
import sys

TIMEOUT = r"(\d{2,}):(\d{2}):(\d{2})[,.](\d{1,3})"
TIMESTAMP_RE = re.compile(rf"^\s*{TIMEOUT}\s*-->\s*{TIMEOUT}\s*$")
INDEX_RE = re.compile(r"^\s*\d+\s*$")

MS_PER = {"h": 3600000, "m": 60000, "s": 1000}


def _to_ms(h, m, s, ms):
    return int(h) * MS_PER["h"] + int(m) * MS_PER["m"] + int(s) * MS_PER["s"] + int(ms.ljust(3, "0"))


def _fmt(ms):
    h, rem = divmod(ms, MS_PER["h"])
    m, rem = divmod(rem, MS_PER["m"])
    s, milli = divmod(rem, MS_PER["s"])
    return f"{h:02d}:{m:02d}:{s:02d},{milli:03d}"


def parse(text):
    """Parse SRT text (LF or CRLF) into a list of cues.

    Each cue is a dict: {"index", "start_ms", "end_ms", "lines"} where
    lines is the list of text lines of the cue.
    """
    cues = []
    blocks = re.split(r"\n\s*\n", text.replace("\r\n", "\n").strip())
    for block in blocks:
        lines = [ln for ln in block.split("\n") if ln.strip()]
        if not lines:
            continue
        start_i = 0
        if len(lines) > 1 and INDEX_RE.match(lines[0]):
            index = int(lines[0].strip())
            start_i = 1
        else:
            index = None
        match = TIMESTAMP_RE.match(lines[start_i])
        if not match:
            raise ValueError(f"malformed timestamp line: {lines[start_i]!r}")
        g = match.groups()
        cues.append({
            "index": index,
            "start_ms": _to_ms(g[0], g[1], g[2], g[3]),
            "end_ms": _to_ms(g[4], g[5], g[6], g[7]),
            "lines": lines[start_i + 1:],
        })
    return cues


def serialize(cues):
    """Emit canonical SRT: renumbered indices, HH:MM:SS,mmm timestamps,
    blank line between cues, single trailing newline."""
    out = []
    for i, cue in enumerate(cues, start=1):
        out.append(f"{i}\n{_fmt(cue['start_ms'])} --> {_fmt(cue['end_ms'])}\n" + "\n".join(cue["lines"]))
    return "\n\n".join(out) + "\n"


def shift(cues, ms):
    """Shift all cues by ms milliseconds. Raises ValueError if any
    resulting start time would be negative."""
    for cue in cues:
        if cue["start_ms"] + ms < 0:
            raise ValueError(
                f"shift by {ms} ms would push cue at {_fmt(cue['start_ms'])} before t=0"
            )
    return [
        {**cue, "start_ms": cue["start_ms"] + ms, "end_ms": cue["end_ms"] + ms}
        for cue in cues
    ]


def scale(cues, factor):
    """Scale all times by factor (from t=0), e.g. retiming 23.976 -> 25 fps."""
    return [
        {
            **cue,
            "start_ms": round(cue["start_ms"] * factor),
            "end_ms": round(cue["end_ms"] * factor),
        }
        for cue in cues
    ]


def lint(cues):
    """Return warnings for overlapping cues, gaps shorter than 40 ms,
    and cues longer than 7 seconds."""
    warnings = []
    for i, cue in enumerate(cues, start=1):
        duration = cue["end_ms"] - cue["start_ms"]
        if duration > 7000:
            warnings.append(
                f"cue {i} ({_fmt(cue['start_ms'])}) duration {duration} ms exceeds 7 seconds"
            )
        if i > 1:
            prev = cues[i - 2]
            gap = cue["start_ms"] - prev["end_ms"]
            if gap < 0:
                warnings.append(
                    f"cue {i} ({_fmt(cue['start_ms'])}) overlaps previous cue "
                    f"(ends at {_fmt(prev['end_ms'])})"
                )
            elif gap < 40:
                warnings.append(
                    f"cue {i} starts after a {gap} ms gap "
                    f"(shorter than 40 ms after cue ending {_fmt(prev['end_ms'])})"
                )
    return warnings


def main(argv=None):
    ap = argparse.ArgumentParser(description="Parse, re-time, and lint SRT subtitles.")
    ap.add_argument("input", help="input .srt file")
    ap.add_argument("--shift", type=int, default=0, metavar="MS",
                    help="shift all cues by MS milliseconds")
    ap.add_argument("--scale", type=float, default=1.0, metavar="FACTOR",
                    help="scale all times from t=0 by FACTOR (e.g. 25/23.976)")
    ap.add_argument("--out", metavar="FILE", help="write result to FILE (default: stdout)")
    ap.add_argument("--lint", action="store_true",
                    help="report overlaps, gaps shorter than 40 ms, and cues longer than 7 s")
    args = ap.parse_args(argv)

    with open(args.input, encoding="utf-8-sig") as f:
        cues = parse(f.read())

    exit_code = 0
    if args.shift:
        cues = shift(cues, args.shift)
    if args.scale != 1.0:
        cues = scale(cues, args.scale)

    if args.lint:
        warnings = lint(cues)
        for w in warnings:
            print(f"WARN: {w}", file=sys.stderr)
            print(f"WARN: {w}")
        if not warnings:
            print("OK: no issues found")
        else:
            exit_code = 1

    output = serialize(cues)
    if args.out:
        with open(args.out, "w", encoding="utf-8", newline="\n") as f:
            f.write(output)
    else:
        sys.stdout.write(output)
    return exit_code


if __name__ == "__main__":
    sys.exit(main())

